using HealthPlatform.Application;using HealthPlatform.Persistence;using HealthPlatform.Contracts;using MassTransit;using Microsoft.EntityFrameworkCore;
namespace HealthPlatform.Workers;
public sealed class WorkerActor(IConfiguration config):ICurrentActor {public Guid TenantId=>Guid.Parse(config["TenantId"]??throw new InvalidOperationException("Configure worker TenantId"));public string Subject=>"notification-worker";public bool IsPatient=>false;public bool IsPractitioner=>false;public bool RecentMfa=>false;public string CorrelationId=>Guid.NewGuid().ToString("N");}
/// <summary>At-least-once outbox dispatch. EventId is stable across retries; subscribers must deduplicate.</summary>
public sealed class NotificationWorker(IServiceScopeFactory scopes,ILogger<NotificationWorker> log):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<HealthDbContext>();var bus=scope.ServiceProvider.GetRequiredService<IPublishEndpoint>();var messages=await db.Outbox.Where(x=>x.DeliveredAt==null).OrderBy(x=>x.CreatedAt).Take(50).ToListAsync(ct);foreach(var m in messages){await bus.Publish(new ProfileNotification(m.Id,m.TenantId,m.Recipient,m.ReferenceId,m.Type),ct);m.DeliveredAt=DateTime.UtcNow;await db.SaveChangesAsync(ct);}}catch(OperationCanceledException)when(ct.IsCancellationRequested){break;}catch(Exception){log.LogWarning("Outbox delivery failed; retrying. No clinical payload logged.");}await Task.Delay(TimeSpan.FromSeconds(3),ct);}}
}
